    function scGetColumnOrderRule($fieldName)
    {
        $sortRule = 'nosort';
        if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_trafico']['ordem_cmp'] == $fieldName) {
            if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_trafico']['ordem_label'] == 'desc') {
                $sortRule = 'desc';
            } else {
                $sortRule = 'asc';
            }
        }
        return $sortRule;
    }

    function scGetColumnOrderIcon($fieldName, $sortRule)
    {        if ('desc' == $sortRule) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort_desc . "\" />";
        } elseif ('asc' == $sortRule) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort_asc . "\" />";
        } elseif ('' != $this->Ini->Label_sort) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort . "\" />";
        } else {
            return '';
        }
    }

    function scIsFieldNumeric($fieldName)
    {
        switch ($fieldName) {
            case "hora":
                return true;
            case "a":
                return true;
            case "ar":
                return true;
            case "m":
                return true;
            case "b2":
                return true;
            case "b3":
                return true;
            case "b4":
                return true;
            case "c2":
                return true;
            case "c3":
                return true;
            case "c4":
                return true;
            case "c5":
                return true;
            case "c6":
                return true;
            case "c7":
                return true;
            case "c8":
                return true;
            case "c9":
                return true;
            case "exe":
                return true;
            case "elu":
                return true;
            case "total":
                return true;
            case "ar1":
                return true;
            case "ar2":
                return true;
        }
        return false;
    }

    function scGetDefaultFieldOrder($fieldName)
    {
        switch ($fieldName) {
            case "hora":
                return 'desc';
            case "a":
                return 'desc';
            case "ar":
                return 'desc';
            case "m":
                return 'desc';
            case "b2":
                return 'desc';
            case "b3":
                return 'desc';
            case "b4":
                return 'desc';
            case "c2":
                return 'desc';
            case "c3":
                return 'desc';
            case "c4":
                return 'desc';
            case "c5":
                return 'desc';
            case "c6":
                return 'desc';
            case "c7":
                return 'desc';
            case "c8":
                return 'desc';
            case "c9":
                return 'desc';
            case "exe":
                return 'desc';
            case "elu":
                return 'desc';
            case "fechaoperacion":
                return 'desc';
            case "fechaturno":
                return 'desc';
            case "ar1":
                return 'desc';
            case "ar2":
                return 'desc';
        }
        return 'asc';
    }

